SCORE_BASE=[[60,62,64,65],[67,65,64,62],[64,65,67,69],[67,64,62,60]]
def erroraudio(name,kind,bar):
    es=[]
    for b,notes in enumerate(SCORE_BASE):
        for j,m in enumerate(notes):
            e=dict(start=.4+(b*4+j)*.4,duration=.32,notes=[m])
            if b==bar:
                if kind=='pitch' and j==1:e['notes']=[m+2]
                if kind=='intonation' and j==2:e['cents']=[45]
                if kind=='articulation':e['duration']=.09
                if kind=='rhythm' and j==0:e['duration']=.52
                if kind=='rhythm' and j==1:e['start']+=.2;e['duration']=.12
            es.append(e)
    return render(name,es)
for kind,b,stem,why in [
 ('pitch',1,'Follow the printed concert-pitch score. In which measure does the recording contain a wrong pitch?','In measure 2, the second note is played as G4 instead of the written F4. The other measures match their written pitches.'),
 ('rhythm',2,'All printed notes are quarters. In which measure does the recording instead begin with a dotted-quarter/eighth pair?','Measure 3 delays its second attack by half a beat: the first duration is dotted-quarter and the second is an eighth. The pair still occupies two beats, so the later attacks and bar length stay aligned.'),
 ('intonation',3,'Follow the score. In which measure is one note conspicuously sharp relative to its written equal-tempered pitch, without becoming the next semitone?','In measure 4, the third note, D4, is raised by 45 cents. The deviation is less than a semitone and is a tuning error, not a different written scale step. The remaining notes use equal-tempered tuning.'),
 ('articulation',0,'The score specifies equal, gently separated quarter notes throughout. In which measure are all notes played markedly shorter than the others?','Measure 1 has sounding durations of 0.09 seconds instead of 0.32 seconds, at the same 0.40-second beat spacing. Only articulation changes; all pitch onsets and the tempo remain correct.')]:
    correct=f'measure {b+1}'; ds=[f'measure {i+1}' for i in range(4) if i!=b]
    add(5,stem,correct,*ds,why,erroraudio('error_'+kind,kind,b),score={'bars':SCORE_BASE,'meter':'4/4','instruction':'Concert pitch • treble clef • all quarter notes • moderately detached, equal length','alt':'Four bars in 4/4, treble clef, no key signature. All notes are quarters. Measure 1: C4 D4 E4 F4. Measure 2: G4 F4 E4 D4. Measure 3: E4 F4 G4 A4. Measure 4: G4 E4 D4 C4.'},evidence={'kind':'error','errorType':kind,'measure':b+1,'written':SCORE_BASE})

# Theory, 17 items.
add(6,'A viola part uses alto clef with its C-clef centered on the third staff line. Which pitch is notated on that line?', 'C4 (middle C)','C3','G4','F3','The center of a C-clef marks middle C. In alto clef it is on the third line. C3 is an octave low; G4 and F3 belong to other reference positions.')
add(6,'A passage in 9/8 is conducted in three. Which note value represents one conducted beat?', 'dotted quarter','quarter','dotted half','eighth','In compound triple meter, nine eighths form three groups of three. Each conducted beat is a dotted quarter, not a single subdivision or a two-eighth quarter.')
add(6,'A conductor asks the ensemble to observe a written subito piano after a forte passage. Which change is required?', 'an immediate change to soft volume','a gradual decrease in volume','an immediate decrease in tempo','a gradual increase in tempo','Subito means suddenly, and piano means soft. A gradual decrease would be diminuendo; neither marking changes tempo.')
add(6,'A key signature contains B-flat, E-flat, A-flat, and D-flat. A melody consistently settles on F with a minor tonic triad. Which key is most likely?', 'F minor','A-flat major','C minor','B-flat minor','Four flats support A-flat major or its relative F minor. The stated tonal center and minor tonic identify F minor. C minor has three flats and B-flat minor five.')
add(7,'An ascending interval is spelled F4 to D-sharp5. Which interval name is correct?', 'augmented sixth','minor seventh','major sixth','diminished seventh','F to D is a sixth by letter count. F to D-natural is a major sixth; raising D to D-sharp augments it. The enharmonic minor seventh would be spelled E-flat, not D-sharp.')
add(7,'A melody uses E–F–G–A–B–C–D–E and repeatedly resolves to E. Which mode best describes it?', 'Phrygian','Dorian','Aeolian','Mixolydian','E Phrygian has a minor second above its tonic. E Aeolian has F-sharp, Dorian adds C-sharp as well, and Mixolydian has G-sharp and C-sharp.')
add(7,'A motive C4–D4–E4 is followed by E4–F-sharp4–G-sharp4 with identical durations. Which device best describes the second motive?', 'real sequence up a major third','diatonic sequence in C major','retrograde of the first motive','inversion around C4','Every note moves up four semitones, retaining the exact interval pattern: a real sequence. A C-major diatonic sequence would use F and G naturals. Neither note order nor interval direction is reversed.')
add(7,'A quarter–quarter–half-note motive returns as eighth–eighth–quarter with unchanged pitches. Which transformation is used?', 'diminution','augmentation','retrograde','melodic inversion','Each duration is halved, which is rhythmic diminution. Augmentation lengthens values, retrograde reverses order, and inversion changes melodic direction.')
add(8,'In C major, a chord has the notes F–A-flat–C-flat–E-flat, with F in the bass. Which label describes its quality?', 'half-diminished seventh','fully diminished seventh','minor seventh','dominant seventh','F–A-flat–C-flat is diminished and E-flat is a minor seventh above F, giving half-diminished quality. A fully diminished seventh would use E-double-flat; minor seventh needs C-natural; dominant seventh also needs A-natural.')
add(8,'A G7 chord in C major is voiced D3–F3–G3–B3. Which inversion symbol is appropriate?', 'V4/3','V6/5','V4/2','V7','D is the fifth of G7 and is in the bass, so the chord is in second inversion, V4/3. V6/5 has B in the bass; V4/2 has F; root position has G.')
add(8,'In C minor, A-flat–C–E-flat–F-sharp resolves toward a G-major dominant. Which chromatic predominant is present?', 'German augmented sixth','French augmented sixth','Neapolitan sixth','Italian augmented sixth','The pitches are lowered 6, 1, lowered 3, and raised 4: a German augmented sixth. French substitutes D for E-flat; Italian omits E-flat; Neapolitan sixth is a first-inversion D-flat major triad.')
add(8,'Over a sustained C-major harmony, an upper voice moves E4–F4–E4 in equal eighth notes, with F on a weak subdivision. What is F?', 'upper neighbor tone','passing tone','suspension','anticipation','F departs by step from E and returns to E, making an upper neighbor. A passing tone continues to a different chord tone, a suspension is prepared and held into dissonance, and an anticipation belongs to an upcoming chord.')
add(8,'A phrase in A minor ends with F major in first inversion followed by E major in root position. Which cadence is most specifically indicated?', 'Phrygian half cadence','perfect authentic cadence','plagal cadence','deceptive cadence','iv6–V in minor gives the bass motion F–E, a descending semitone into the dominant: a Phrygian half cadence. Authentic and plagal cadences end on tonic; deceptive typically resolves V to VI.')
add(9,'A movement follows A–B–A–C–A, with A returning in the tonic. Which formal description is most appropriate?', 'five-part rondo','ternary form','binary form','theme and variations','Alternation of a recurring refrain A with contrasting episodes B and C is five-part rondo. Ternary is broadly ABA, binary has two main sections, and variations transform a continuing theme rather than alternate independent episodes.')
add(9,'In a Classical sonata-form movement in G major, the secondary theme appears in D major in the exposition. In the recapitulation, what is the most typical tonal treatment of that theme?', 'it returns in G major','it remains in D major','it returns in E minor','it moves to A major','The recapitulation generally resolves the exposition’s tonic–dominant contrast by bringing the secondary material into the tonic, G major. Keeping or replacing the secondary key does not provide the characteristic tonal resolution.')
add(9,'Two measures of 3/4 are accented as three groups of two quarter notes instead of two groups of three. Which device results?', 'hemiola','syncopated anticipation','rhythmic augmentation','tempo modulation','Hemiola re-groups six units as three twos against two threes. No change of the basic quarter-note speed or systematic doubling of a motive is required.')
add(9,'In a fugue, the answer alters an interval of the subject to avoid an early move away from the tonic–dominant relationship. Which term applies?', 'tonal answer','real answer','stretto','countersubject','A tonal answer modifies intervals to maintain tonal relationships. A real answer is an exact transposition; stretto overlaps entries; a countersubject is recurring counterpoint accompanying the subject.')

# Creating / performing, 17.
add(10,'An arranger wants a B-flat trumpet to sound concert E-flat4. Which pitch should be written?', 'F4','D-flat4','E-flat4','F5','A B-flat trumpet sounds a major second below written pitch. Writing F4 produces E-flat4. D-flat moves the wrong way; E-flat ignores transposition; F5 adds an unwanted octave.')
add(10,'A horn in F must sound concert C4. Which pitch should the arranger write?', 'G4','F4','G3','C4','Horn in F sounds a perfect fifth below written pitch. Written G4 sounds C4. G3 is an octave too low; F4 and C4 do not supply the required fifth transposition.')
add(10,'A teacher arranges a melody for beginning singers whose comfortable range is D4–B4. The original spans G4–E5. Which transposition best places its entire range within the stated limits?', 'down a perfect fourth','down a major second','up a perfect fourth','down an octave','G4–E5 shifted down a perfect fourth becomes D4–B4. Down a second leaves D5 above the limit; up a fourth raises it further; down an octave places G3 below the range.')
add(10,'Students can improvise a two-measure question over a C-pentatonic drone. Which next task most directly develops coherent phrase relationships?', 'answer using a shared rhythm and a tonic ending','change pitch collection on every beat','add unrelated pitches at maximum speed','copy the question without any ending change','Reusing a rhythmic idea creates unity and ending on tonic gives the answer closure. Random rapid changes obscure phrase relationships; exact copying alone does not deliberately shape a complementary answer.')
add(11,'A beginning singer lifts the shoulders and takes a noisy, tense breath before every phrase. Which instruction is most appropriate first?', 'inhale quietly with released shoulders and expanding lower ribs','hold the breath firmly before phonation','raise the chin and pull in the abdomen','push the shoulders upward to increase capacity','A quiet, unforced inhalation with released shoulders and flexible rib expansion promotes coordinated breathing. Breath holding and forceful posture changes add tension rather than addressing it.')
add(11,'An adolescent singer has new register breaks and a changing comfortable range. What is the most appropriate response?', 'recheck the range regularly and adapt the part','retain the old part and require more volume','stop all singing until adulthood','assign a permanent adult category immediately','Changing voices need ongoing range/tessitura checks and adaptable parts. Forcing the old range risks strain, complete exclusion is unnecessary, and a permanent adult classification is premature.')
add(11,'A choir has accurate pitches but inconsistent sustained vowels. Which rehearsal activity most directly improves blend?', 'agree on a vowel shape and sustain it on a shared pitch','increase consonant duration on every syllable','ask each singer to maximize individual vibrato','increase the tempo of the passage','Shared vowel formation aligns resonance and timbre. Longer consonants do not align sustained vowels; individual exaggeration reduces blend; a tempo change does not diagnose vowel inconsistency.')
add(11,'A young singer reports pain while producing a high note. What should the teacher do first?', 'stop the painful task and use a comfortable, unforced range','repeat the note more loudly to strengthen it','ask for a tighter jaw to stabilize pitch','require the note in every warm-up','Pain is a signal to stop the task, not force repetition. Use comfortable, unforced singing and follow appropriate referral procedures if symptoms persist; increased tension or loudness is not a remedy.')
add(12,'A beginning flutist produces mostly air noise. Which adjustment should the teacher investigate first?', 'directing a focused airstream across the embouchure edge','pressing a reed harder against the lower lip','tightening a mouthpiece buzz','increasing bow pressure near the bridge','Flute tone depends on a focused airstream interacting with the embouchure edge. Reeds, brass buzzing, and bowed-string technique belong to different tone-production systems.')
add(12,'A clarinet student repeatedly squeaks while crossing the break. Which first check is most appropriate?', 'complete finger-hole coverage and coordinated motion','maximum jaw pressure on the reed','removing the register key from use','loosening every finger away from the keys','Leaks and poorly coordinated changes can cause squeaks around the break. Check coverage and motion before prescribing force; excessive biting and avoiding necessary keys do not teach the required coordination.')
add(12,'A violin student produces a scratchy tone during a sustained note. Which variables should the teacher help the student coordinate?', 'bow speed, pressure, and contact point','reed strength, ligature, and tongue height','valve combinations, slide length, and breath','pedal depth, hammer speed, and release','Bowed-string tone depends on the balance among bow speed, pressure/weight, and contact point. The other sets refer to woodwinds, brass, or keyboard mechanisms.')
add(12,'A beginning recorder player gets unstable, overblown low notes. Which strategy is most appropriate?', 'use a gentle steady air stream and fully seal the holes','increase air pressure and lift fingers higher','bite the mouthpiece while opening the thumb hole','tongue harder while leaving small finger leaks','Low recorder notes require secure hole coverage and controlled gentle air. Extra pressure can overblow; biting and leaks destabilize the tone. Tonguing cannot compensate for an unsealed tube.')
add(13,'A band plays a sustained unison with audible beats between players. Which rehearsal sequence best targets the problem?', 'isolate small groups, compare pitch, and adjust while listening','repeat the whole piece faster without stopping','add percussion to conceal the beats','ask all players to increase vibrato','Small-group comparison makes pitch discrepancies audible and permits adjustment. Faster repetition, masking, and increased vibrato obscure rather than resolve the intonation problem.')
add(13,'A piece in 6/8 moves at a brisk dotted-quarter pulse. Which conducting approach most clearly communicates its main beat structure?', 'two beats per measure, each subdividing into three','six equal main beats regardless of tempo','three beats per measure, each subdividing into two','one beat for every written quarter note','At this tempo, 6/8 is compound duple: two dotted-quarter beats. Six gestures may be useful at slow tempos but contradict the stated main pulse; three twos imply simple triple.')
add(13,'After a long rest, a section repeatedly enters late. Which conducting preparation most directly supports an accurate entrance?', 'eye contact followed by a clear preparatory breath and beat','an abrupt large gesture only after the attack','continuous attention to a different section','a cutoff gesture on the entrance beat','A cue must prepare the sound before the attack, conveying timing and character. A late gesture cannot prepare an entrance, and a cutoff or diverted attention gives the wrong information.')
add(13,'A director selects repertoire for an ensemble with limited rehearsal time and uneven reading skill. Which criterion is most important?', 'musical value with attainable technical and reading demands','the highest published difficulty rating','the greatest possible number of independent parts','the director’s preferred recording tempo alone','Repertoire must offer musical substance and productive challenge within the ensemble’s current resources. Difficulty, density, or a recording tempo alone does not establish suitability.')
add(13,'An accompanist is overpowering a student choir in a rehearsal room. Which adjustment best supports the singers?', 'reduce accompaniment density and level while preserving harmonic cues','double every voice at full volume','omit the harmonic rhythm entirely','accelerate to shorten the exposure','A lighter, quieter texture preserves pitch/harmonic support while allowing singers to hear themselves. Loud doubling masks them; eliminating structure or speeding up does not address balance.')

# History/culture/context, 22.
add(14,'A sacred vocal work uses a single unaccompanied melodic line and follows the accents of a Latin liturgical text. Which historical repertory is most consistent?', 'medieval plainchant','Baroque chorale cantata','Classical mass with orchestra','Romantic sacred oratorio','Monophonic unaccompanied Latin liturgical melody points to plainchant. The other repertories characteristically involve composed multi-part and/or instrumental textures, unlike the description.')
add(14,'A teacher compares two Renaissance motets. Which feature would most strongly support their period identification?', 'successive points of vocal imitation based on text phrases','a solo melody over a continuo bass throughout','a sonata exposition with contrasting tonal areas','a twelve-tone row controlling pitch order','Renaissance motets commonly organize polyphony around imitative entries tied to text phrases. Continuo is Baroque, sonata exposition is later instrumental practice, and serial ordering is twentieth century.')
add(14,'A class studies Barbara Strozzi to broaden its account of seventeenth-century composition. Which repertoire most directly represents her contribution?', 'secular vocal cantatas and arias','Classical string quartets','Romantic symphonic poems','Renaissance cyclic masses','Strozzi is particularly associated with seventeenth-century secular vocal music, including cantatas and arias. The other genres belong to different periods or are not her characteristic contribution.')
add(14,'A nineteenth-century orchestral work uses folk-derived dance rhythms to assert a national identity. Which broader movement does this most directly illustrate?', 'musical nationalism','medieval organum','Classical cosmopolitan galant style','postwar total serialism','Adapting folk and dance materials to express national identity is musical nationalism. The other descriptions concern earlier styles or a later compositional system, not this social purpose.')
add(14,'A unit pairs Florence Price’s orchestral music with discussion of spiritual-derived melodic idioms and barriers faced by Black women composers. Which interpretive approach is most sound?', 'analyze both compositional craft and historical context','treat biography as a substitute for score study','assume every passage directly quotes a spiritual','exclude social context from all musical interpretation','Combining score-based craft analysis with documented historical context gives a fuller account. Biography alone neglects the music; unverified quotation claims overreach; excluding context erases relevant conditions.')
add(15,'A class traces the blues through both its form and expressive practices. Which combination is most characteristic?', 'AAB lyric pattern with flexible blue-note inflection','through-composed Latin text with unison chant','strict five-voice counterpoint with cantus firmus','da capo aria with orchestral ritornello','AAB text patterns and flexible blue-note inflection are characteristic blues practices, though not universal rules. The other descriptions point to chant, contrapuntal sacred writing, or Baroque aria.')
add(15,'An arrangement gives saxophones, trumpets, and trombones coordinated sectional riffs while a rhythm section supports featured solos. Which jazz context best fits?', 'swing-era big band','solo stride piano','early vocal field holler','unaccompanied barbershop quartet','Sectional brass/reed writing with rhythm section and solo features is a big-band practice. The other options lack the described instrumental sections and arranged ensemble texture.')
add(15,'A class examines the adaptation of spirituals into concert choral arrangements. Which historical context is especially relevant?', 'African American community, faith, and the legacy of enslavement','the establishment of European court minuet etiquette','the invention of twelve-tone composition','the exclusive use of notation before oral performance','Spirituals emerged in African American religious and communal life under enslavement and continued in varied forms, including concert arrangements. Court dance, serialism, and a notation-first account do not explain that history.')
add(15,'A recording features banjo, fiddle, mandolin, guitar, and bass, with tight high vocal harmonies and instrumental breaks. Which US tradition is most consistent?', 'bluegrass','bebop','synth-pop','brass-band march','This acoustic string lineup, vocal style, and solo-break practice are characteristic of bluegrass. Bebop uses different jazz idioms; synth-pop centers electronic production; a brass band has a different instrumental family.')
add(15,'A teacher studies how songs were adapted for mass participation during the US civil rights movement. Which function is most directly illustrated?', 'building solidarity through shared singing','separating performers from collective action','eliminating earlier community musical traditions','replacing all spoken political communication','Shared, adaptable songs supported solidarity and participation. They often drew on existing traditions and complemented rather than eliminated other forms of communication.')
add(16,'A class studies a Javanese gamelan piece in which large gongs mark structural points within repeating cycles. Which concept best explains the gong parts?', 'colotomic organization','functional dominant–tonic cadence','twelve-bar harmonic progression','equal-tempered chromatic sequence','Colotomic organization articulates recurring time cycles through specific instruments at structural points. Western functional harmony, blues form, and equal temperament should not be imposed as its defining system.')
add(16,'A Balkan dance is notated in 7/8 with beat groups 2+2+3. Which rehearsal action best preserves its characteristic organization?', 'step short–short–long while maintaining equal eighth notes','stress seven equally strong conducting beats','replace the final group with two eighth notes','stretch every eighth note to a different duration','The eighth-note units remain equal while the larger beats have unequal lengths. Short–short–long embodies 2+2+3. Equal main accents hide the grouping; deleting or distorting units changes the meter.')
add(16,'A lesson on West African drumming uses a recording from one named community and identifies interlocking parts around a recurring timeline. Which conclusion is most responsible?', 'the example shows one specific practice within diverse traditions','the example defines all African music','the example lacks structure because it uses oral transmission','the example must be understood through major–minor harmony','A named tradition should be studied in its own setting, not generalized to a continent. Oral transmission can be highly structured, and Western tonal harmony need not be its organizing framework.')
add(16,'A class learns about mariachi in a Mexican community celebration. Which instrumental combination is most characteristic?', 'violins, trumpets, vihuela, and guitarrón','sitar, tabla, and tanpura','shamisen, shakuhachi, and koto','accordion, bagpipes, and bodhrán','Modern mariachi commonly uses violins, trumpets, and distinctive plucked string instruments including vihuela and guitarrón. The other combinations draw from different traditions and do not identify mariachi.')
add(17,'A composer records kitchen sounds, cuts them into fragments, changes their playback speed, and assembles a piece. Which practice is most directly illustrated?', 'musique concrète','figured-bass realization','species counterpoint','equal-temperament tuning','Musique concrète uses recorded real-world sounds as compositional material and transforms them. Figured bass and species counterpoint are not recording processes; temperament concerns tuning relationships.')
add(17,'A student exports a MIDI file and expects it to contain the exact sound of a recorded choir. What must the teacher clarify?', 'MIDI stores performance messages, not the recorded waveform','MIDI always contains microphone recordings','MIDI guarantees the same sound on every playback device','MIDI can store tempo but never pitch','MIDI represents events such as note, velocity, and control data. Sound depends on the playback instrument; it does not contain the original acoustic waveform and can represent both tempo and pitch.')
add(17,'How did the development of valves most directly expand the capabilities of brass instruments?', 'it enabled convenient chromatic pitch changes by altering tubing length','it replaced lip vibration with a reed','it made all instruments nontransposing','it eliminated the need to select partials with the embouchure','Valves route air through added tubing, expanding available chromatic pitches. Brass still uses lip vibration and partial selection, and transposition is a notation convention not abolished by valves.')
add(17,'A class compares pre-recording local performance traditions with modern streaming distribution. Which claim is best supported?', 'recording and networks expanded circulation beyond live local audiences','streaming removed all economic gatekeeping','recording made live music culturally unnecessary','digital files guarantee payment to every performer','Recording and networks change reach and listening practices. Claims that gatekeeping disappears, live music becomes unnecessary, or all contributors are paid are unsupported absolutes.')
add(18,'A school commissions a musician to create a short recurring brand theme for announcements. Which musical function is primary?', 'commercial or institutional identity through a sonic cue','liturgical observance through fixed worship text','private practice of instrumental technique','archival transcription without interpretation','A recurring identifiable theme can serve branding or institutional identity. Worship, private technique, and archival work have different primary purposes.')
add(18,'A composer wants to place an existing commercial recording in a film. Which action is most appropriate before release?', 'secure the applicable composition and master-recording permissions','credit the performer and assume permission is automatic','buy one streaming subscription for the production','assume a short excerpt is always exempt','Film use generally involves composition synchronization and recording/master rights, subject to the specific circumstances. Credit or streaming access does not supply those licenses; no blanket short-excerpt exemption exists.')
add(18,'A student enjoys diagnosing microphones, balancing recorded tracks, and preparing mixes. Which career most directly uses those interests?', 'audio engineer','instrument conservator','orchestral librarian','music therapist','Audio engineers work with recording, signal flow, and mixing. Conservators maintain physical instruments, librarians manage performance materials, and music therapy is a credentialed clinical discipline.')
add(18,'At a community memorial, participants sing a familiar song together without a formal audience–performer division. Which role is most evident?', 'communal expression and shared remembrance','competitive ranking of technical virtuosity','advertising a new commercial product','demonstrating the superiority of notation over memory','Participatory memorial singing can express shared grief, memory, and belonging. The scenario provides no basis for competition, advertising, or a hierarchy between written and remembered music.')

# Pedagogy, 22.
add(19,'Kindergartners can echo a short song but cannot yet read its rhythm. Which next step most appropriately links sound to notation?', 'move and clap the known pattern, then connect it to symbols','begin with silent copying of unfamiliar sixteenth-note patterns','require written definitions before hearing the pattern','replace singing with a spelling worksheet','Starting from a known aural/motor pattern and connecting it to symbols builds meaningful literacy. Unfamiliar abstraction or unrelated writing does not establish the sound–symbol relationship.')
add(19,'A second-grade class is learning to maintain a steady beat. Which activity most directly assesses that target?', 'walk evenly to a song while its surface rhythm changes','clap every syllable of the text','name the instruments in a recording','draw the contour of the melody','Even movement through changing surface rhythms reveals steady-beat maintenance. Syllable clapping follows rhythm, and timbre/contour tasks measure different targets.')
add(19,'Students improvise on barred instruments while a teacher sustains a C–G drone. Which setup best supports initial success with C-major pentatonic material?', 'offer C, D, E, G, and A bars','offer only F-sharp, G-sharp, and A-sharp bars','require chromatic scales at full speed','assign every available bar without modeling','C-major pentatonic offers a manageable collection over the C–G drone. Unrelated sharps or unscaffolded chromatic demands do not match the stated tonal and developmental goal.')
add(19,'A teacher silently gestures a familiar song’s middle phrase while children continue singing it internally, then cues the last phrase aloud. Which skill is targeted?', 'audiation','absolute-pitch labeling','score copying','instrument classification','Continuing to hear and understand music internally during silence is audiation. The task does not require absolute pitch names, written copying, or instrument identification.')
add(19,'An elementary teacher uses a tablet app for students to record and compare two performances of a short rhythm. Which use best supports learning?', 'listen for one agreed criterion and choose a revision','judge improvement only by the number of recordings','use decorative filters instead of listening','post identifiable recordings publicly by default','Focused comparison on a criterion connects technology to feedback and revision. Counts and decoration do not show rhythmic growth, and public sharing requires appropriate permissions and safeguards.')
add(20,'A middle school band understands a difficult rhythm when clapping but loses it while playing a passage. Which next scaffold is most appropriate?', 'play the rhythm on one comfortable pitch before restoring the line','return immediately to full-speed performance of the whole piece','introduce a harder fingering pattern with the same rhythm','remove all rhythmic counting from rehearsal','A single-pitch transfer isolates instrument coordination before adding melodic complexity. Full-speed repetition or harder fingerings increases load without bridging the demonstrated gap.')
add(20,'A secondary choir is learning movable-do solfege in a major key. Which task most directly checks functional pitch understanding rather than memorized letter names?', 'sing the same solfege phrase in a different key','recite the alphabet from A to G','copy the key signature without singing','identify a composer’s birth date','Successful transposition of solfege preserves scale-degree relationships across keys. Alphabet recitation, copying, and historical recall do not demonstrate that functional understanding.')
add(20,'Beginning high-school improvisers freeze when given an unrestricted solo. Which task provides the most useful initial structure?', 'create a two-bar answer using three chord tones and a fixed pulse','improvise through every key with no tonal reference','memorize definitions instead of producing sound','match a professional solo immediately at recording speed','Limiting materials and phrase length makes musical decision-making manageable while preserving creativity. Unrestricted complexity, purely verbal work, or expert-speed imitation is not a comparable scaffold.')
add(20,'A general music class is producing multitrack songs. Which assignment best develops intentional use of digital tools?', 'revise one layer to improve a stated balance or texture goal','add every available effect to every track','maximize track count regardless of the musical result','evaluate work only by the software brand used','A named musical goal and purposeful revision connect technology to musicianship. Effects, track count, and brands alone do not measure artistic or technical understanding.')
add(21,'A teacher wants to measure individual growth in sight-singing over a semester. Which plan gives the strongest evidence?', 'compare baseline and final equivalent tasks with the same analytic rubric','compare the final concert applause with last year’s applause','grade only attendance at rehearsals','compare different students on unrelated tasks','Comparable individual tasks and consistent criteria support valid growth claims. Applause, attendance, and non-equivalent comparisons do not isolate the same sight-singing construct over time.')
add(21,'Two teachers assign very different scores to the same recorded performances using the same rubric. Which action most directly improves interrater reliability?', 'calibrate ratings using shared examples and discuss criterion interpretation','replace the rubric with an unstructured overall impression','average only the highest scores','give students a longer performance piece','Calibration establishes shared interpretations of criteria. Unstructured impressions can worsen consistency, while selective averaging or longer pieces does not solve rater disagreement.')
add(21,'The target is accurate rhythmic performance, but a test awards most points for spelling Italian terminology. What is the primary assessment concern?', 'weak validity because evidence does not match the target','low reliability caused solely by repeated measurement','an appropriate direct measure of performance accuracy','excessive alignment between task and target','The assessment samples vocabulary instead of the intended rhythmic performance, creating a validity problem. Reliability is consistency; a consistently scored test can still measure the wrong construct.')
add(21,'Exit recordings show most students sustain a pulse but misread ties across the bar line. What is the best instructional response?', 'reteach ties with spoken counts, held sound, and a short transfer task','restart the whole unit without using the evidence','focus the next lesson only on instrument history','raise grades because pulse was partly correct','The evidence identifies a specific misconception. Targeted instruction and a transfer check address it while retaining what students can already do. Broad restart, unrelated content, and grade inflation do not.')
add(22,'A student says a performance feels tense. Which response best develops an evidence-based aesthetic judgment?', 'identify dissonance, register, and rhythm that support that impression','replace the response with the teacher’s preference','rank the performance only by its duration','insist that emotional responses cannot be discussed','Interpretive claims become more articulate when supported by audible musical features. Teacher preference or duration alone is not evidence, and personal responses can be discussed critically without pretending they are universal.')
add(22,'A class compares the repetition of a visual motif with the return of a musical theme. Which connection is most defensible?', 'both can create unity while allowing varied contexts','both must communicate an identical literal meaning','both always require exact mechanical duplication','both eliminate contrast from the artwork','Recurring elements can unify works across arts while changing context creates variety. Neither literal sameness, mechanical exactness, nor elimination of contrast follows from repetition.')
add(22,'Music and science teachers plan a sound unit. Which project most authentically integrates both disciplines?', 'measure vibrating-string changes and compose using the resulting pitch relationships','play background music during unrelated laboratory notes','replace musical creation with a vocabulary-only worksheet','grade a composition only on laboratory-report formatting','Measuring physical relationships and using them in composition gives both scientific inquiry and musical creation substantive roles. Background music and one-sided grading do not integrate disciplinary learning.')
add(22,'Students evaluate two compositions written for a short suspense scene. Which criterion most directly fits the artistic task?', 'how musical choices shape tension and support the scene','which composition uses the greatest number of notes','which composer owns the newest software','which piece most closely matches the teacher’s favorite genre','Evaluation should align with the purpose: how sound shapes tension and dramatic pacing. Note quantity, equipment, and personal genre preference do not establish effectiveness for the scene.')
add(23,'A student with limited hand mobility wants to perform the class ostinato. Which first response best supports meaningful inclusion?', 'collaborate on an accessible playing method that preserves the rhythmic role','assign unrelated written work for every performance','excuse the student from all musical participation','require the same grip regardless of access needs','Adapt the method or interface while preserving meaningful musical participation, informed by the student and relevant support team. Automatic exclusion and inflexible grips do not provide access to the shared goal.')
add(23,'An English learner understands a song through singing but struggles with spoken instructions. Which support is most appropriate?', 'model the task with visuals and concise repeated language','lower every musical goal because of English proficiency','replace participation with silent observation','give longer verbal explanations without examples','Modeling, visuals, and concise language improve access without confusing language proficiency with musical capacity. Lowered expectations, exclusion, or more unsupported speech do not address the barrier.')
add(23,'A student rapidly masters the class’s melodic dictation work. Which extension best serves this learner?', 'analyze ambiguous phrases and compose a more complex dictation for peers','repeat identical easy exercises for the remaining unit','assign unrelated clerical work as the sole extension','remove all feedback because the student is advanced','Greater musical complexity and creative transfer offer appropriate challenge. Repetition and clerical work do not deepen learning; advanced students still need meaningful feedback.')
add(23,'A learner with sensory sensitivities becomes overwhelmed during loud percussion activities. Which plan is most appropriate?', 'coordinate agreed supports, predictable cues, and a manageable sound level','surprise the learner with loud sounds to build tolerance','exclude the learner from all ensemble work automatically','ignore the response if other students are comfortable','Individualized, predictable access supports should be coordinated with the student and appropriate team. Forced surprise, automatic exclusion, and dismissal of distress do not support safe participation.')
add(23,'A student’s individualized education program specifies accessible notation and extra processing time. What should the music teacher do?', 'implement the accommodations and coordinate with the IEP team','wait until the student fails before providing them','substitute a private personal plan without consultation','ask classmates to decide whether the supports are fair','The teacher must implement applicable IEP provisions and collaborate with the team. Accommodations are not contingent on failure or peer approval, and unilateral replacement bypasses the student’s plan.')

