# Balance correct positions without a predictable A/B/C/D cycle.
import random
rng=random.Random(2122026)
keys=list(range(4))*25;rng.shuffle(keys)
for q,k in zip(BANK,keys):
    correct=q['options'][q['answer']]; ds=[v for i,v in enumerate(q['options']) if i!=q['answer']];rng.shuffle(ds);ds.insert(k,correct);q['options']=ds;q['answer']=k
(ROOT/'questions.json').write_text(json.dumps(BANK,indent=2,ensure_ascii=False))
media={name:'data:audio/wav;base64,'+base64.b64encode((ROOT/'audio'/info['file']).read_bytes()).decode() for name,info in AUDIO.items()}
template=(ROOT/'template.html').read_text()
for marker,value in {'__BANK__':json.dumps(BANK,ensure_ascii=False).replace('</','<\\/'),'__AUDIO__':json.dumps(media),'__CORE__':(ROOT/'core.js').read_text(),'__AREAS__':json.dumps(AREAS),'__TITLES__':json.dumps(TITLES),'__TIPS__':json.dumps(TIPS)}.items():template=template.replace(marker,value)
